def get_current_identity(api_key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0401000" if __import__("os").path.isdir("./environment_mix/0401000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string", field="api_key")

    t0 = time.time()
    now = _now()

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")

    key_in = api_key.strip()
    key_row = None
    for k in api_keys:
        if isinstance(k, dict) and (k.get("id") == key_in or k.get("key_prefix") == key_in):
            key_row = k
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "api_key is missing or invalid")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is not active")

    exp = _parse_dt(key_row.get("expires_at"))
    if exp is not None and exp <= now:
        # Transition to expired if possible (active->expired)
        if key_row.get("status") == "active":
            key_row["status"] = "expired"
            key_row["updated_at"] = _iso(now)
            _save("api_keys.json", api_keys)
        return _err("UNAUTHORIZED", "api_key is expired")

    client_row = None
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == key_row.get("client_id"):
            client_row = c
            break
    if client_row is None:
        return _err("UNAUTHORIZED", "api_key is invalid (client not found)")
    if client_row.get("status") != "active":
        return _err("UNAUTHORIZED", "client is not active")

    rate_limit = client_row.get("default_rate_limit_per_minute")
    if not isinstance(rate_limit, int) or rate_limit < 1:
        rate_limit = 60

    window_start = now - datetime.timedelta(seconds=60)
    used = 0
    for sr in search_requests:
        if not isinstance(sr, dict):
            continue
        if sr.get("api_key_id") != key_row.get("id"):
            continue
        created = _parse_dt(sr.get("created_at"))
        if created is None:
            continue
        if created >= window_start:
            used += 1

    remaining = max(0, rate_limit - used)

    # Update last_used_at for identity call? Unsplash-like identity endpoint may count; we do not create search_requests
    # because schema has no general request log; keep observable dynamics via updating last_used_at.
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    return {
        "identity": {
            "api_key": {
                "id": key_row.get("id"),
                "key_prefix": key_row.get("key_prefix"),
                "status": key_row.get("status"),
                "expires_at": key_row.get("expires_at"),
                "last_used_at": key_row.get("last_used_at"),
                "client_id": key_row.get("client_id"),
                "created_at": key_row.get("created_at"),
                "updated_at": key_row.get("updated_at"),
            },
            "client": {
                "id": client_row.get("id"),
                "name": client_row.get("name"),
                "status": client_row.get("status"),
                "default_rate_limit_per_minute": client_row.get("default_rate_limit_per_minute"),
                "notes": client_row.get("notes"),
                "created_at": client_row.get("created_at"),
                "updated_at": client_row.get("updated_at"),
            },
            "scopes": ["public"],  # schema does not model scopes; provide minimal stable default
        },
        "rate_limit": {
            "limit_per_minute": rate_limit,
            "used_in_window": used,
            "remaining_in_window": remaining,
            "window_seconds": 60,
        },
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
            "server_time": _iso(now),
        }
    }

def list_api_clients(api_key, status=None, name_contains=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0401000" if __import__("os").path.isdir("./environment_mix/0401000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        s = cur.strip()
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        if not isinstance(obj, dict) or "offset" not in obj:
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        off = obj.get("offset")
        if not isinstance(off, int) or off < 0:
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
        return off

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string", field="api_key")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
            return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked", field="status")
    if name_contains is not None and (not isinstance(name_contains, str)):
        return _err("VALIDATION_ERROR", "name_contains must be a string", field="name_contains")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")

    t0 = time.time()
    now = _now()

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")

    # Authenticate
    key_in = api_key.strip()
    key_row = None
    for k in api_keys:
        if isinstance(k, dict) and (k.get("id") == key_in or k.get("key_prefix") == key_in):
            key_row = k
            break
    if key_row is None or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is missing or invalid")

    # Expiration check
    exp = _parse_dt(key_row.get("expires_at"))
    if exp is not None and exp <= now:
        if key_row.get("status") == "active":
            key_row["status"] = "expired"
            key_row["updated_at"] = now.isoformat().replace("+00:00", "Z")
            _save("api_keys.json", api_keys)
        return _err("UNAUTHORIZED", "api_key is expired")

    # Cursor -> offset
    offset = 0
    if cursor is not None:
        off = _decode_cursor(cursor)
        if isinstance(off, dict) and off.get("error"):
            return off
        offset = off

    # Filter and sort created_at desc
    rows = [c for c in api_clients if isinstance(c, dict)]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]
    if name_contains is not None and name_contains.strip():
        sub = name_contains.strip().lower()
        rows = [c for c in rows if isinstance(c.get("name"), str) and sub in c["name"].lower()]

    def _sort_key(c):
        dt = _parse_dt(c.get("created_at"))
        # None => very old
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page_rows = rows[offset: offset + limit]
    next_offset = offset + len(page_rows)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    # Observable dynamics: record as a received->succeeded no-op search_request? Not appropriate.
    # We do count identity/list usage toward key last_used_at.
    key_row["last_used_at"] = now.isoformat().replace("+00:00", "Z")
    key_row["updated_at"] = key_row["last_used_at"]
    _save("api_keys.json", api_keys)

    # Return clients visible: for this simplified store, all clients are visible to any authenticated key.
    return {
        "data": page_rows,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "total": total,
            "has_more": has_more,
        },
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def update_api_client(api_key, id, name=None, default_rate_limit_per_minute=None, notes=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0401000" if __import__("os").path.isdir("./environment_mix/0401000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_api_client"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(search_requests_rows, status, client_id=None, api_key_id=None, error_code=None, error_message=None, cache_key=None):
        now = _now()
        rid = _gen_id("uns_srq")
        row = {
            "id": rid,
            "client_id": client_id,
            "api_key_id": api_key_id,
            "status": status,
            "query_text": None,
            "page": None,
            "per_page": None,
            "cache_key": cache_key or f"{endpoint}:{rid}",
            "cache_hit": False,
            "upstream_provider": "unsplash",
            "upstream_request_id": None,
            "upstream_status_code": None,
            "error_code": error_code,
            "error_message": error_message,
            "result_count": None,
            "started_at": None,
            "completed_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        search_requests_rows.append(row)
        return row

    def _auth(api_key_value, api_keys_rows, api_clients_rows):
        now = _now()
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None, None, _err("UNAUTHORIZED", "api_key is missing or invalid")
        ak = api_key_value.strip()
        candidates = [k for k in api_keys_rows if k.get("id") == ak or k.get("key_prefix") == ak]
        if not candidates:
            return None, None, _err("UNAUTHORIZED", "api_key is missing or invalid")

        for k in candidates:
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            cid = k.get("client_id")
            c = next((r for r in api_clients_rows if r.get("id") == cid), None)
            if not c:
                continue
            if c.get("status") != "active":
                continue
            return k, c, None

        return None, None, _err("UNAUTHORIZED", "Invalid/expired/revoked api_key.")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")

    used_key, used_client, auth_err = _auth(api_key, api_keys, api_clients)
    if auth_err:
        req = _log(search_requests, "failed", None, None, "AUTH_REQUIRED", auth_err["error"]["message"])
        req["completed_at"] = req["created_at"]
        req["updated_at"] = req["created_at"]
        _save("search_requests.json", search_requests)
        return auth_err

    if not isinstance(id, str) or not id.strip():
        req = _log(search_requests, "failed", used_client.get("id"), used_key.get("id"), "VALIDATION_ERROR", "id must be a non-empty string")
        req["completed_at"] = req["created_at"]
        req["updated_at"] = req["created_at"]
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    target_id = id.strip()

    row = next((c for c in api_clients if c.get("id") == target_id), None)
    if not row:
        req = _log(search_requests, "failed", used_client.get("id"), used_key.get("id"), "NOT_FOUND", "api_client not found")
        req["completed_at"] = req["created_at"]
        req["updated_at"] = req["created_at"]
        _save("search_requests.json", search_requests)
        return _err("NOT_FOUND", "api_client not found")

    # Validate provided fields
    if name is not None:
        if not isinstance(name, str) or not name.strip():
            req = _log(search_requests, "failed", used_client.get("id"), used_key.get("id"), "VALIDATION_ERROR", "name must be a non-empty string")
            req["completed_at"] = req["created_at"]
            req["updated_at"] = req["created_at"]
            _save("search_requests.json", search_requests)
            return _err("VALIDATION_ERROR", "name must be a non-empty string")
        new_name = name.strip()
        # unique(name) (excluding self)
        if any(c.get("id") != target_id and isinstance(c.get("name"), str) and c.get("name").strip().lower() == new_name.lower() for c in api_clients):
            msg = "api_clients.name must be unique"
            req = _log(search_requests, "failed", used_client.get("id"), used_key.get("id"), "CONFLICT", msg)
            req["completed_at"] = req["created_at"]
            req["updated_at"] = req["created_at"]
            _save("search_requests.json", search_requests)
            return _err("CONFLICT", msg)

    if default_rate_limit_per_minute is not None:
        if not isinstance(default_rate_limit_per_minute, int):
            req = _log(search_requests, "failed", used_client.get("id"), used_key.get("id"), "VALIDATION_ERROR", "default_rate_limit_per_minute must be an integer")
            req["completed_at"] = req["created_at"]
            req["updated_at"] = req["created_at"]
            _save("search_requests.json", search_requests)
            return _err("VALIDATION_ERROR", "default_rate_limit_per_minute must be an integer")
        if default_rate_limit_per_minute < 1 or default_rate_limit_per_minute > 6000:
            msg = "default_rate_limit_per_minute must be between 1 and 6000 (schema constraint)"
            req = _log(search_requests, "failed", used_client.get("id"), used_key.get("id"), "VALIDATION_ERROR", msg)
            req["completed_at"] = req["created_at"]
            req["updated_at"] = req["created_at"]
            _save("search_requests.json", search_requests)
            return _err("VALIDATION_ERROR", msg)

    if notes is not None and not isinstance(notes, str):
        req = _log(search_requests, "failed", used_client.get("id"), used_key.get("id"), "VALIDATION_ERROR", "notes must be a string if provided")
        req["completed_at"] = req["created_at"]
        req["updated_at"] = req["created_at"]
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "notes must be a string if provided")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
            req = _log(search_requests, "failed", used_client.get("id"), used_key.get("id"), "VALIDATION_ERROR", "invalid status")
            req["completed_at"] = req["created_at"]
            req["updated_at"] = req["created_at"]
            _save("search_requests.json", search_requests)
            return _err("VALIDATION_ERROR", "invalid status")
        current = row.get("status")
        transitions = {
            "active": ("suspended", "revoked"),
            "suspended": ("active", "revoked"),
            "revoked": (),
        }
        if status != current and status not in transitions.get(current, ()):
            msg = f"Illegal status transition {current}→{status} (lifecycle rule)"
            req = _log(search_requests, "failed", used_client.get("id"), used_key.get("id"), "INVALID_TRANSITION", msg)
            req["completed_at"] = req["created_at"]
            req["updated_at"] = req["created_at"]
            _save("search_requests.json", search_requests)
            return _err("INVALID_TRANSITION", msg)

    # Apply updates
    changed = False
    now = _now()

    if name is not None:
        row["name"] = name.strip()
        changed = True
    if default_rate_limit_per_minute is not None:
        row["default_rate_limit_per_minute"] = int(default_rate_limit_per_minute)
        changed = True
    if notes is not None:
        row["notes"] = notes
        changed = True
    if status is not None and status != row.get("status"):
        row["status"] = status
        changed = True

    if not changed:
        # No success without effect on mutations
        req = _log(search_requests, "failed", used_client.get("id"), used_key.get("id"), "VALIDATION_ERROR", "No fields to update")
        req["completed_at"] = req["created_at"]
        req["updated_at"] = req["created_at"]
        _save("search_requests.json", search_requests)
        return _err("VALIDATION_ERROR", "No fields to update")

    row["updated_at"] = _iso(now)
    _save("api_clients.json", api_clients)

    used_key["last_used_at"] = _iso(now)
    used_key["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    req = _log(search_requests, "succeeded", used_client.get("id"), used_key.get("id"))
    req["started_at"] = req["created_at"]
    req["completed_at"] = req["created_at"]
    req["result_count"] = 1
    req["updated_at"] = req["created_at"]
    _save("search_requests.json", search_requests)

    return {"api_client": row, "request": {"id": req["id"], "status": req["status"], "latency_ms": int((time.time() - t0) * 1000)}}
